import numpy as np
x=np.load('source_pixels.npz')['rgb'][0].astype(int)
# classify pixels into coarse color categories and print 2x2 blocks crop
def cls(c):
 r,g,b=c; mx=max(c); mn=min(c); s=mx-mn
 if mx<45:return '#'
 if mx<75:return '@'
 if mx<105:return '%'
 if s<14:
  return '.' if mx<110 else ':' if mx<155 else '-' if mx<200 else '+'
 if r>g+15 and r>b+25:
  return 'R' if mx>160 else 'r'
 if g>r+10 and g>b+5:
  return 'G' if mx>130 else 'g'
 if b>r+10 and b>g+5:
  return 'B' if mx>120 else 'b'
 if r>g+12 and g>b+12:
  return 'Y' if mx>175 else 'y'
 if r>b+20 and b>g+10:
  return 'M' if mx>150 else 'm'
 if g>r+8 and b>r+5:
  return 'C' if mx>120 else 'c'
 return '?'
for y0,y1 in [(55,110),(35,90),(90,144)]:
 print('\\nY',y0,y1)
 for y in range(y0,y1,2):
  row=''
  for xx in range(0,256,2):
   c=x[y:y+2,xx:xx+2].mean((0,1))
   row+=cls(c)
  print(f'{y:3d} '+row)
 print('    '+''.join(str((xx//10)%10) for xx in range(0,256,2)))
PY"

